use customer_behaviour;

CREATE DATABASE customer_behaviour;

use customer_behaviour;

SELECT * FROM customer;

-- Q1. What is the total revenue generated by male vs. female customers?
SELECT gender,SUM(purchase_amount) AS Revenue FROM customer GROUP BY gender;

-- 02. Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id,purchase_amount FROM customer WHERE discount_applied = 'Yes' AND purchase_amount >= (SELECT AVG(purchase_amount) FROM customer);

-- 03. Which are the top 5 products with the highest average review rating? 
SELECT item_purchased,AVG(review_rating) AS Average_Review_Rating FROM customer GROUP BY item_purchased ORDER BY Average_Review_Rating DESC LIMIT 5;

-- 04. Compare the average Purchase Amounts between Standard and Express Shipping. 
SELECT shipping_type,AVG(purchase_amount) AS Average_Purchase_Amount FROM customer WHERE shipping_type IN ('Standard','Express') GROUP BY shipping_type;

-- 05. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.
SELECT subscription_status,COUNT(customer_id) AS Total_Customers,AVG(purchase_amount) AS Average_Spend, SUM(purchase_amount) AS Revenue FROM customer GROUP BY subscription_status; 

-- 06. Which 5 products have the highest percentage of purchases with discounts applied? 
SELECT item_purchased, ROUND(100 * SUM(CASE WHEN  discount_applied = 'Yes' THEN 1 ELSE 0 END)/COUNT(*),2) as discount_rate
FROM customer GROUP BY item_purchased ORDER BY discount_rate DESC LIMIT 5;
-- --07. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment.
WITH customer_type as (
select customer_id, previous_purchases,
CASE WHEN previous_purchases = 1 THEN 'New'
WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
ELSE 'Loyal'
END AS customer_segment
FROM customer
)
SELECT customer_segment,COUNT(*) AS Number_of_Customers FROM customer_type 
GROUP BY customer_segment;

-- --08. What are the top 3 most purchased products within each category?
WITH item_counts AS (SELECT category, item_purchased, COUNT(customer_id) AS total_orders,
ROW_NUMBER() OVER (PARTITION BY category ORDER BY count(customer_id) DESC) AS item_rank
FROM customer GROUP BY category, item_purchased)
SELECT item_rank, category, item_purchased, total_orders FROM
item_counts WHERE item_rank <= 3;

-- --09. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT subscription_status, COUNT(customer_id) AS repeat_buyers FROM customer WHERE
previous_purchases > 5 GROUP BY subscription_status;

-- --010. What is the revenue contribution of each age group?
SELECT age, SUM(purchase_amount) AS total_revenue FROM customer
GROUP BY age ORDER BY total_revenue DESC;
